1	/**
2	*
3	* # OTEL Collector (K8s Addon)
4	* Deploys otel collector via terraform.
5	* ## Created Resources
6	* 1. otel collector.
7	*
8	*/
9	terraform {
10	  required_version = ">= 1.3.0"
11	
12	  required_providers {
13	    helm = {
14	      source  = "hashicorp/helm"
15	      version = "~> 2.0"
16	    }
17	    kubernetes = {
18	      source  = "hashicorp/kubernetes"
19	      version = "~> 2.0"
20	    }
21	  }
22	}
23	
24	resource "kubernetes_namespace" "this" {
25	  metadata {
26	    name = var.namespace
27	
28	    #labels = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/otel-collector" })
29	
30	    annotations = var.annotations
31	  }
32	}
33	
34	resource "kubernetes_manifest" "otel-collector" {
35	  manifest = {
36	    "apiVersion" = "external-secrets.io/v1"
37	    "kind"       = "ExternalSecret"
38	    "metadata" = {
39	      "name" = "otel-collector"
40	      "namespace" = var.namespace
41	    }
42	    "spec" = {
43	      "refreshInterval" = "1h0m0s"
44	      "secretStoreRef" = {
45	        "name" = "vault"
46	        "kind" = "ClusterSecretStore"
47	      }
48	      "target" = {
49	        "name"           = "otel-collector"
50	        "creationPolicy" = "Owner"
51	      }
52	      "data" = [
53	        {
54	          "secretKey" = "DD_API_KEY"
55	          "remoteRef" = {
56	            "key"      = "secret/data/saas/infrastructure/datadog-api-key"
57	            "property" = "apiKey"
58	          }
59	        },
60	      ]
61	    }
62	  }
63	  depends_on = [kubernetes_namespace.this]
64	}
65	
66	
67	resource "helm_release" "otel_collector_lb" {
68	  #name      = var.name
69	  name = "otel-collector-lb"
70	  namespace = var.namespace
71	  create_namespace = false
72	  repository = "https://open-telemetry.github.io/opentelemetry-helm-charts/"
73	  chart      = "opentelemetry-collector"
74	  version    = var.chart_version
75	
76	  values = [yamlencode({
77	    mode = "deployment"
78	    image = {
79	      repository = var.otellb_image
80	      tag = var.image_tag_version
81	    }
82	    replicaCount = var.otel_lb_replicas
83	
84	    nameOverride = "collector"
85	
86	    annotations = var.annotations
87	
88	    podLabels = {
89	      "ic-ops.net/otel" = "collector"
90	      "app.kubernetes.io/part-of" = "opentelemetry-collector"
91	    }
92	
93	    #serviceAccount = {
94	    #  create = true,
95	    #  name   = var.otellb_sa_name,
96	    #  annotations = var.sa_annotations
97	    #}
98	
99	    presets = {
100	      # enables the k8sattributesprocessor and adds it to the traces, metrics, and logs pipelines
101	      kubernetesAttributes = {
102	        enabled = true
103	        extractAllPodLabels = false
104	        extractAllPodAnnotations = true
105	      }
106	    }
107	
108	    serviceAccount = {
109	      create = true,
110	      name   = var.otellb_sa_name
111	      annotations = var.sa_annotations
112	    }
113	
114	    command = {
115	      extraArgs = var.otellb_extra_args
116	    }
117	
118	    ports = {
119	      otlp = {
120	        enabled = true
121	        containerPort = 4317
122	        servicePort = 4317
123	        protocol = "TCP"
124	        appProtocol = "grpc"
125	      }
126	      otlp-http = {
127	        enabled = true
128	        containerPort = 4318
129	        servicePort = 4318
130	        protocol = "TCP"
131	      }
132	      jaegar-compact = {
133	        enabled = false
134	      }
135	      jaeger-grpc = {
136	        enabled = false
137	      }
138	      jaeger-thrift = {
139	        enabled = false
140	      }
141	      zipkin = {
142	        enabled = false
143	      }
144	    }
145	
146	    config = local.lb_config
147	  })]
148	
149	  depends_on = [
150	    kubernetes_namespace.this,
151	    kubernetes_manifest.otel-collector,
152	    helm_release.otel_collector_processor
153	  ]
154	}
155	
156	resource "helm_release" "otel_collector_processor" {
157	  #name      = var.name
158	  name = "otel-collector-processor"
159	  namespace = var.namespace
160	  create_namespace = false
161	  repository = "https://open-telemetry.github.io/opentelemetry-helm-charts/"
162	  chart      = "opentelemetry-collector"
163	  version    = var.chart_version
164	
165	  values = [yamlencode({
166	    mode = "statefulset"
167	    image = {
168	      repository = var.otel_image
169	      tag        = var.image_tag_version
170	    }
171	    statefulset = {
172	      persistentVolumeClaimRetentionPolicy = {
173	        enabled     = true
174	        whenDeleted = "Delete"
175	        whenScaled  = "Delete"
176	      }
177	
178	      volumeClaimTemplates = [
179	        {
180	          metadata = {
181	            name = "otel-collector-data"
182	          }
183	          spec = {
184	            accessModes = ["ReadWriteOnce"]
185	            resources = {
186	              requests = {
187	                storage = var.otel_pv_size
188	              }
189	            }
190	            //storageClassName = var.otel_storage_class_name
191	          }
192	        }
193	      ]
194	    }
195	
196	    extraVolumeMounts = [{
197	      name       = "otel-collector-data"
198	      mountPath  = "/var/lib/storage/queue"
199	    }]
200	
201	    initContainers = [{
202	      name  = "init-fs"
203	      image = "busybox:latest"
204	      command = ["sh", "-c", "chown -R 10001: /var/lib/storage/queue"]
205	      volumeMounts = [{
206	        name      = "otel-collector-data"
207	        mountPath = "/var/lib/storage/queue"
208	      }]
209	    }]
210	
211	    nameOverride = "processor"
212	
213	    replicaCount = var.otel_collector_replicas
214	
215	    service = {
216	      type = "ClusterIP"
217	      clusterIP = "None" # Headless service for statefulset
218	    }
219	
220	    annotations = var.annotations
221	    podLabels = {
222	      "ic-ops.net/otel" = "processor"
223	      "app.kubernetes.io/part-of" = "opentelemetry-collector"
224	    }
225	
226	    serviceAccount = {
227	      create = true,
228	      name   = var.otel_sa_name,
229	      annotations = var.sa_annotations
230	    }
231	
232	    command = {
233	      extraArgs = var.extra_args
234	    }
235	
236	    extraEnvsFrom = [{
237	      secretRef = {
238	        name = "otel-collector"
239	      }
240	    }]
241	
242	    #presets = {
243	      # enables the k8sattributesprocessor and adds it to the traces, metrics, and logs pipelines
244	      #kubernetesAttributes = {
245	      #  enabled = true
246	      #  extractAllPodLabels = true
247	      #  extractAllPodAnnotations = true
248	      #}
249	    #}
250	
251	    ports = {
252	      otlp = {
253	        enabled = true
254	        containerPort = 4317
255	        servicePort = 4317
256	        protocol = "TCP"
257	        appProtocol = "grpc"
258	      }
259	      otlp-http = {
260	        enabled = true
261	        containerPort = 4318
262	        servicePort = 4318
263	        protocol = "TCP"
264	      }
265	      jaegar-compact = {
266	        enabled = false
267	      }
268	      jaeger-grpc = {
269	        enabled = false
270	      }
271	      jaeger-thrift = {
272	        enabled = false
273	      }
274	      zipkin = {
275	        enabled = false
276	      }
277	    }
278	
279	    config = local.otel_config
280	  })]
281	
282	  depends_on = [
283	    kubernetes_namespace.this,
284	    kubernetes_manifest.otel-collector
285	  ]
286	
287	  lifecycle {
288	    create_before_destroy = false
289	  }
290	}
291	
292	module "netpol" {
293	  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/security/network-policy.git?ref=v1.1.0"
294	
295	  name             = join("-", [var.name, "netpol"])
296	  namespace        = var.namespace
297	  network_policies = local.netpols
298	
299	  tags = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/otel-collector" })
300	
301	  depends_on = [
302	    kubernetes_namespace.this
303	  ]
304	}
