47	      }
48	    }
49	
50	    service = {
51	      extensions = ["health_check","file_storage/persistent_queue"]
52	      pipelines = {
53	        traces = {
54	          receivers = ["otlp"]
55	          processors = []
56	          exporters = ["datadog/connector", "datadog/exporter"]
57	        }
58	
59	        logs = {
60	          receivers = ["otlp"]
61	          processors = []
62	          exporters = ["datadog/exporter"]
63	        }
64	
65	        metrics = {
66	          receivers = ["otlp", "datadog/connector"]
67	          processors = []
68	          exporters = ["datadog/exporter"]
69	        }
70	      }
71	      telemetry = {
72	        logs = {
73	          encoding = "json"
74	        }
75	      }
76	    }
77	  }
78	}
