1	locals {
2	  lb_config = {
3	    receivers = {
4	      otlp = {
5	        protocols = {
6	          grpc = {
7	            endpoint = "0.0.0.0:4317"
8	          }
9	          http = {
10	            endpoint = "0.0.0.0:4318"
11	          }
12	        }
13	      }
14	    }
15	
16	    processors = {
17	      k8sattributes = {
18	        auth_type = "serviceAccount"
19	        extract = {
20	          metadata = [
21	            "k8s.namespace.name",
22	            "k8s.deployment.name",
23	            "k8s.statefulset.name",
24	            "k8s.daemonset.name",
25	            "k8s.cronjob.name",
26	            "k8s.job.name",
27	            "k8s.node.name",
28	            "k8s.pod.name",
29	            "k8s.pod.uid",
30	            "k8s.pod.start_time"
31	          ]
32	          labels = [{
33	            key_regex = "tags\\.datadoghq\\.com/(.*)$"
34	            tag_name = "$$1"
35	            from = "pod"
36	          }]
37	        }
38	        passthrough = false
39	        pod_association = [
40	          {
41	            sources = [{
42	              from = "resource_attribute"
43	              name = "k8s.pod.ip"
44	            }]
45	          },
46	          {
47	            sources = [{
48	              from = "resource_attribute"
49	              name = "k8s.pod.uid"
50	            }]
51	          },
52	          {
53	            sources = [{
54	              from = "connection"
55	            }]
56	          }
57	        ]
58	      }
59	    }
60	
61	    exporters = {
62	      loadbalancing = {
63	        routing_key = "traceID"
64	        protocol = {
65	          otlp = {
66	            # all options from the OTLP exporter are supported
67	            # except the endpoint
68	            timeout = "2s"
69	            tls = {
70	              insecure = true
71	            }
72	          }
73	        }
74	        resolver = {
75	          # Notice to config a headless service DNS in Kubernetes
76	          dns = {
77	            hostname = "otel-collector-processor.${var.namespace}.svc.cluster.local"
78	          }
79	        }
80	      }
81	      #metrics loadbalancing
82	      "loadbalancing/metrics" = {
83	        routing_key = "service"
84	        protocol = {
85	          otlp = {
86	            # all options from the OTLP exporter are supported
87	            # except the endpoint
88	            timeout = "2s"
89	            tls = {
90	              insecure = true
91	            }
92	          }
93	        }
94	        resolver = {
95	          # Notice to config a headless service DNS in Kubernetes
96	          dns = {
97	            hostname = "otel-collector-processor.${var.namespace}.svc.cluster.local"
98	          }
99	        }
100	      }
101	    }
102	
103	    service = {
104	      pipelines = {
105	        traces = {
106	          receivers = ["otlp"]
107	          processors = ["k8sattributes"]
108	          exporters = ["loadbalancing"]
109	        }
110	
111	        logs = {
112	          receivers = ["otlp"]
113	          processors = ["k8sattributes"]
114	          exporters = ["loadbalancing"]
115	        }
116	
117	        metrics = {
118	          receivers = ["otlp"]
119	          processors = ["k8sattributes"]
120	          exporters = ["loadbalancing/metrics"]
121	        }
122	      }
123	      telemetry = {
124	        logs = {
125	          encoding = "json"
126	        }
127	      }
128	    }
129	  }
130	}
